class Solution {
  private static final int MAX = 100_001;
  private static final int[] MU = mobius(MAX); // computed once and shared by every test case

  private static int[] mobius(int limit) {
    int[] mu = new int[limit], primes = new int[limit];
    boolean[] composite = new boolean[limit];
    int count = 0;
    mu[1] = 1;
    for (int i = 2; i < limit; i++) {
      if (!composite[i]) {
        primes[count++] = i;
        mu[i] = -1;
      }
      for (int j = 0; j < count && (long) i * primes[j] < limit; j++) {
        int p = primes[j];
        composite[i * p] = true;
        if (i % p == 0) {
          mu[i * p] = 0;
          break;
        }
        mu[i * p] = -mu[i];
      }
    }
    return mu;
  }

  public int maxScore(int[] nums, int maxVal) {
    int n = nums.length, limit = maxVal;
    for (int v : nums) limit = Math.max(limit, v);
    limit++; // no value can exceed max(maxVal, max(nums)), so no table needs to be larger
    int[] freq = new int[limit], multiples = new int[limit], coprime = new int[limit];
    for (int v : nums) freq[v]++;
    for (int d = 1; d < limit; d++) for (int m = d; m < limit; m += d) multiples[d] += freq[m];
    for (int d = 1; d < limit; d++) {
      if (MU[d] == 0) continue;
      for (int m = d; m < limit; m += d) coprime[m] += MU[d] * multiples[d];
    }
    long best = Long.MIN_VALUE;
    for (int v = 1; v < limit; v++) {
      int cnt = n - coprime[v]; // elements sharing a factor with v
      if (v <= maxVal) best = Math.max(best, (long) v - (cnt > 0 ? cnt : 1)); // turn one element into v
      if (freq[v] > 0) best = Math.max(best, (long) v - (cnt - (v > 1 ? 1 : 0))); // keep an existing v
    }
    return (int) best;
  }
}
